package com.procurement.approvalrule.mapper;
import com.procurement.approvalrule.entity.*; import com.procurement.approvalrule.dto.request.*; import com.procurement.approvalrule.dto.response.*; import com.procurement.department.entity.Department; import org.springframework.stereotype.Component;
@Component public class ApprovalRuleMapper { public ApprovalRule toEntity(ApprovalRuleRequest r,Department d){var e=new ApprovalRule(); update(e,r,d);return e;} public void update(ApprovalRule e,ApprovalRuleRequest r,Department d){e.setRuleCode(r.ruleCode());e.setRuleName(r.ruleName());e.setDepartment(d);e.setMinimumAmount(r.minimumAmount());e.setMaximumAmount(r.maximumAmount());e.setActive(r.active()==null||r.active());e.setDescription(r.description());} public ApprovalRuleResponse toResponse(ApprovalRule e){return new ApprovalRuleResponse(e.getId(),e.getRuleCode(),e.getRuleName(),e.getDepartment().getId(),e.getDepartment().getDepartmentName(),e.getMinimumAmount(),e.getMaximumAmount(),e.getActive(),e.getDescription(),e.getCreatedBy(),e.getUpdatedBy(),e.getCreatedAt(),e.getUpdatedAt());} }
